import React from "react";
import { Icon } from "@traveloka/soya-components";

import * as style from "./FloatButton.styles";

class FloatButtonChildren extends React.Component {
  render() {
    const { text, icon, onClick } = this.props;
    return (
      <div className={style.floatButtonChildren} onClick={onClick}>
        <div className={style.labelContainer}>
          <div className={style.labelText}>{text}</div>
        </div>
        <div className={style.buttonChildren}>
          <Icon icon={icon} />
        </div>
      </div>
    );
  }
}

export default FloatButtonChildren;
